ui.css:
.panel { background: #2b2446; border-radius: 3px; padding: 7px 14px; color: #fff; font: 600 15px/1.3 'Chakra Petch', system-ui, sans-serif;
  box-shadow: inset 0 3px 0 rgba(255,255,255,.16), inset 3px 0 0 rgba(255,255,255,.07), inset 0 -4px 0 rgba(0,0,0,.38), inset -3px 0 0 rgba(0,0,0,.22), 0 0 0 3px #151024, 0 6px 0 3px #151024, 0 10px 18px rgba(10,6,24,.35); }
.bar { width: 216px; height: 22px; background: #160f22; border-radius: 2px; overflow: hidden; box-shadow: inset 0 3px 0 rgba(0,0,0,.55), 0 0 0 2px #0e0a18; }
.bar > .fill { height: 100%; background: repeating-linear-gradient(90deg, rgba(0,0,0,0) 0 15px, rgba(50,8,16,.8) 15px 18px), linear-gradient(180deg, #ffb09a 0 22%, #f0443a 22% 70%, #b3242a 70% 100%); }
.bar.mint > .fill { background: repeating-linear-gradient(90deg, rgba(0,0,0,0) 0 15px, rgba(16,40,40,.75) 15px 18px), linear-gradient(180deg, #c8ffee 0 20%, #57e6b4 20% 68%, #26a888 68% 100%); }
.big-number { font: 400 34px/1.05 'Bungee', sans-serif; color: #ffc23e; letter-spacing: 2px; text-shadow: 0 2px 0 #d9741c, 0 4px 0 #a2470f, 0 6px 0 #151024; }
